struct Prefix {
    std::uint64_t key;       // normalized upper-64 network address
    std::uint64_t endExcl;   // key + 2^(64-len); 0 means "wraps past 2^64"
    std::uint64_t value;     // packed (hop, len)
    std::uint32_t len;
};

Prefix makePrefix(std::uint64_t key, std::uint32_t len, std::uint64_t hop) {
    Prefix p;
    p.key = (len == 0) ? 0u : (key & (~std::uint64_t(0) << (64 - len)));
    p.len = len;
    p.value = packValue(hop, len);
    p.endExcl = (len == 0) ? 0u : p.key + (std::uint64_t(1) << (64 - len));
    return p;
}

void parseFibLine(const char* s, std::size_t n, Prefix& out) {
    std::vector<std::pair<const char*, std::size_t>> tok;
    tok.reserve(3);
    const std::size_t nt = splitTokens(s, n, tok, 2);
    if (nt != 2) fail("FIB record must have exactly two fields");

    const char* p = tok[0].first;
    const std::size_t pn = tok[0].second;
    const char* slash = static_cast<const char*>(std::memchr(p, '/', pn));
    if (slash == nullptr) fail("FIB record is missing '/' before the prefix length");
    const std::size_t addrLen = static_cast<std::size_t>(slash - p);
    const char* lenStr = slash + 1;
    const std::size_t lenLen = pn - addrLen - 1;

    std::uint64_t addr = 0;
    if (!parseIPv6(p, addrLen, addr)) fail("FIB record has an invalid IPv6 address");

    std::uint64_t len = 0;
    if (!parseDigits(lenStr, lenLen, 128, len)) fail("FIB record has an invalid prefix length");
    if (len > static_cast<std::uint64_t>(kMaxPrefixLen)) fail("unsupported prefix length (only 0..64)");

    std::uint64_t hop = 0;
    if (!parseDigits(tok[1].first, tok[1].second, kMaxHop, hop)) fail("FIB record has an invalid next hop");

    out = makePrefix(addr, static_cast<std::uint32_t>(len), hop);
}

std::vector<Prefix> readFib(const std::string& path) {
    FilePtr fp = openRead(path, "FIB");
    LineReader rd(fp.get());
    std::vector<Prefix> prefixes;
    const char* s = nullptr;
    std::size_t n = 0;
    while (rd.next(s, n)) {
        bool blank = true;
        for (std::size_t i = 0; i < n; ++i) {
            if (!isSpaceChar(s[i])) { blank = false; break; }
        }
        if (blank) continue;
        if (prefixes.size() >= kMaxFibRecords) fail("too many FIB records");
        Prefix p;
        parseFibLine(s, n, p);
        prefixes.push_back(p);
    }
    return prefixes;
}

struct Row {
    std::uint64_t start;
    std::uint64_t value;   // packed (hop,len) or kNoMatch
};

std::vector<Row> compileImage(std::vector<Prefix> prefixes) {
    // Reject duplicates of the same normalized (network, length) pair.
    std::sort(prefixes.begin(), prefixes.end(), [](const Prefix& a, const Prefix& b) {
        if (a.key != b.key) return a.key < b.key;
        return a.len < b.len;
    });
    for (std::size_t i = 1; i < prefixes.size(); ++i) {
        if (prefixes[i].key == prefixes[i - 1].key && prefixes[i].len == prefixes[i - 1].len)
            fail("duplicate normalized prefix in FIB");
    }

    // Change points can only be prefix starts or prefix ends (+1); key 0 is
    // always present because the image covers the whole key space.
    std::vector<std::uint64_t> points;
    points.reserve(prefixes.size() * 2 + 1);
    points.push_back(0);
    for (const Prefix& p : prefixes) {
        points.push_back(p.key);
        if (p.endExcl != 0) points.push_back(p.endExcl);
    }
    std::sort(points.begin(), points.end());
    points.erase(std::unique(points.begin(), points.end()), points.end());
    if (points.size() > kMaxImageRows) fail("compiled image has too many rows");

    // Sweep the change points, keeping the longest active prefix in a max-heap
    // with lazy removal of intervals that already ended.
    struct Cmp {
        bool operator()(const Prefix& a, const Prefix& b) const { return a.len < b.len; }
    };
    std::priority_queue<Prefix, std::vector<Prefix>, Cmp> active;
    std::vector<Row> rows;
    rows.reserve(points.size());
    std::size_t next = 0;
    bool havePrev = false;
    std::uint64_t prev = 0;
    for (const std::uint64_t k : points) {
        while (next < prefixes.size() && prefixes[next].key <= k) active.push(prefixes[next++]);
        while (!active.empty()) {
            const Prefix& top = active.top();
            if (top.endExcl != 0 && top.endExcl <= k) active.pop();
            else break;
        }
        const std::uint64_t value = active.empty() ? kNoMatch : active.top().value;
        if (!havePrev || value != prev) {
            rows.push_back(Row{k, value});
            havePrev = true;
            prev = value;
        }
    }
